mapper.update:
UPDATE reconciliation_break
   SET resolution_status = 'RESOLVED',
       resolution_note   = COALESCE(resolution_note, '재대사에서 불일치가 사라졌다'),
       resolved_at       = #{detectedAt}
 WHERE business_date     = #{businessDate}
   AND network           = #{network}
   AND resolution_status IN ('OPEN', 'INVESTIGATING')
   AND last_detected_at  < #{detectedAt}

mapper.select:
SELECT reconciliation_break_id AS reconciliationBreakId, business_date AS businessDate, network, payment_instruction_id AS paymentInstructionId, break_type AS breakType, internal_amount AS internalAmount, external_amount AS externalAmount, external_status AS externalStatus, detail, resolution_status AS resolutionStatus, resolution_note AS resolutionNote, first_detected_at AS firstDetectedAt, last_detected_at AS lastDetectedAt FROM reconciliation_break WHERE business_date = #{businessDate}
AND network = #{network}
ORDER BY break_type, ABS(internal_amount - external_amount) DESC
